INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4222086',2309,97,'P1','AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)','FEPESE - Tec Con (Pref Itajaí)/Pref Itajaí/2026','Caderno Contabilidade Pública Parte 5','De acordo com o Manual de Contabilidade Aplicada ao Setor Público (MCASP – 11ª edição), a natureza da informação contábil patrimonial possui como objetivo principal:','[["A","Registrar, processar e evidenciar os fatos relacionados exclusivamente à execução do orçamento anual e às alterações decorrentes do plano plurianual."],["B","Registrar, processar e evidenciar os atos administrativos cujos efeitos estejam associados apenas ao controle de metas institucionais."],["C","Registrar, processar e evidenciar os fatos relacionados à composição patrimonial, abrangendo somente as variações quantitativas ocorridas."],["D","Registrar, processar e evidenciar os fatos financeiros e não financeiros relacionados à composição do patrimônio público e às suas variações qualitativas e quantitativas."],["E","Registrar, processar e evidenciar as operações vinculadas exclusivamente aos registros de natureza extraorçamentária."]]'::jsonb,'D',2026,24,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Registrar, processar e evidenciar os fatos financeiros e não financeiros relacionados à composição do patrimônio público e às suas variações qualitativas e quantitativas.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb,'De acordo com o Manual de Contabilidade Aplicada ao Setor Público (MCASP – 11ª edição), a natureza da informação contábil patrimonial possui como objetivo principal:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4222108',2310,97,'P1','AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)','FEPESE - Tec Con (Pref Itajaí)/Pref Itajaí/2026','Caderno Contabilidade Pública Parte 5','O Plano de Contas Aplicado ao Setor Público (PCASP) está estruturado de acordo com as seguintes naturezas das informações contábeis:','[["A","Financeira, econômica e operacional."],["B","Fiscal, financeira e tributária."],["C","Patrimonial, orçamentária e de controle."],["D","Corrente, permanente e especial."],["E","Obrigatória, facultativa e complementar."]]'::jsonb,'C',2026,25,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Patrimonial, orçamentária e de controle.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Plano de Contas (PCASP)"}'::jsonb,'O Plano de Contas Aplicado ao Setor Público (PCASP) está estruturado de acordo com as seguintes naturezas das informações contábeis:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4076811',2311,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11)','Unifil - Cont (COHAVEL)/COHAVEL/2026','Caderno Contabilidade Pública Parte 5','As Demonstrações Contábeis Aplicadas ao Setor Público (DCASP) evidenciam informações relevantes sobre a composição do patrimônio público, o desempenho dos governos e os fluxos de caixa. Sobre as DCASP, analise as assertivas e assinale a alternativa correta. I. A entidade deve informar separadamente os ativos e os passivos, as receitas e as despesas. A compensação desses elementos no balanço patrimonial ou na demonstração do resultado, exceto quando refletir a essência da transação ou outro evento, prejudica a capacidade dos usuários de compreender as transações, outros eventos e condições que tenham ocorrido e de avaliar os futuros fluxos de caixa da entidade. II. O Balanço Orçamentário é composto pelo Quadro Principal, pelo Quadro da Execução dos Restos a Pagar Não Processados e pelo Quadro da Execução dos Restos a Pagar Processados. Para sua elaboração são utilizadas as classes de contas 1 a 4 do PCASP. III. Conforme previsto no art. 43 da Lei nº 4.320/1964, o superávit financeiro apurado em balanço patrimonial do exercício anterior constitui fonte para abertura de crédito adicional. No Balanço Orçamentário, tais valores devem ser considerados como receita orçamentária do exercício de referência e serão computados no cálculo do déficit ou superávit orçamentário.','[["A","Apenas III está correta."],["B","Apenas I está correta."],["C","Apenas I e II estão corretas."],["D","Todas estão incorretas."],["E","Apenas I e III estão corretas."]]'::jsonb,'B',2026,26,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Apenas I está correta.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11)"}'::jsonb,'As Demonstrações Contábeis Aplicadas ao Setor Público (DCASP) evidenciam informações relevantes sobre a composição do patrimônio público, o desempenho dos governos e os fluxos de caixa. Sobre as DCASP, analise as assertivas e assinale a alternativa correta. I. A entidade deve informar separadamente os ativos e os passivos, as receitas e as despesas. A compensação desses element') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4152822',2312,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11)','IDECAN - Ana Leg (ALECE)/ALECE/Ciências Contábeis/2026','Caderno Contabilidade Pública Parte 5','De acordo com a NBC TSP 11 (R1), que estabelece a estrutura para a apresentação das demonstrações contábeis no setor público, assinale a alternativa correta quanto à classificação de ativos e passivos e à estrutura das demonstrações.','[["A","Ativos biológicos são classificados invariavelmente como ativos não circulantes, independentemente do seu ciclo de produção ou da expectativa de venda e consumo."],["B","No Balanço Patrimonial, um passivo deve ser classificado como circulante quando se espera que seja liquidado no ciclo operacional normal da entidade, ou quando deva ser liquidado num período de até doze meses após a data de reporte."],["C","As notas explicativas são consideradas elementos facultativos das demonstrações contábeis, devendo ser apresentadas apenas quando houver mudança de critérios de mensuração."],["D","A entidade é dispensada de apresentar informações comparativas em relação ao período anterior, desde que justifique a relevância dos dados atuais no relatório de gestão."],["E","O resultado patrimonial do período deve obrigatoriamente ser apresentado seguindo a classificação das despesas por natureza, sendo vedada a apresentação por função."]]'::jsonb,'B',2026,27,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — No Balanço Patrimonial, um passivo deve ser classificado como circulante quando se espera que seja liquidado no ciclo operacional normal da entidade, ou quando deva ser liquidado num período de até doze meses após a data de reporte.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Introdução às DCASP (Parte V, Capítulo 1 do MCASP e NBC TSP 11)"}'::jsonb,'De acordo com a NBC TSP 11 (R1), que estabelece a estrutura para a apresentação das demonstrações contábeis no setor público, assinale a alternativa correta quanto à classificação de ativos e passivos e à estrutura das demonstrações.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4150596',2313,93,'P1','AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13)','FUNDATEC - Ana Pol Pen (PP RS)/PP RS/Ciências Contábeis/2026','Caderno Contabilidade Pública Parte 5','Considere os seguintes dados extraídos dos registros contábeis de uma unidade da Polícia Penal referentes ao encerramento do exercício de 20X5: Receita Corrente Arrecadada: R$ 600.000. Receita de Capital Arrecadada: R$ 250.000. Despesa Corrente Empenhada: R$ 530.000. Despesa de Capital Empenhada: R$ 200.000. Recebimento de depósitos em caução (extraorçamentário): R$ 45.000. Superávit Financeiro do exercício anterior utilizado para créditos: R$ 80.000. Com base na Lei nº 4.320/1964, o resultado orçamentário apurado no Balanço Orçamentário dessa unidade foi um:','[["A","Superávit orçamentário de R$ 200.000."],["B","Déficit orçamentário de R$ 120.000."],["C","Superávit orçamentário de R$ 165.000."],["D","Superávit orçamentário de R$ 120.000."],["E","Equilíbrio orçamentário (resultado nulo)."]]'::jsonb,'D',2026,28,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Superávit orçamentário de R$ 120.000.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13)"}'::jsonb,'Considere os seguintes dados extraídos dos registros contábeis de uma unidade da Polícia Penal referentes ao encerramento do exercício de 20X5: Receita Corrente Arrecadada: R$ 600.000. Receita de Capital Arrecadada: R$ 250.000. Despesa Corrente Empenhada: R$ 530.000. Despesa de Capital Empenhada: R$ 200.000. Recebimento de depósitos em caução (extraorçamentário): R$ 45.000. Sup') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4193534',2314,93,'P1','AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13)','CEBRASPE (CESPE) - ACI (CGE AL)/CGE AL/2026','Caderno Contabilidade Pública Parte 5','Julgue o próximo item, a respeito de transferências voluntárias, receitas e despesas públicas e execução orçamentária. Considere que uma prefeitura tenha inscrito crédito fiscal de IPTU inadimplente, referente ao exercício de 2021, em dívida ativa durante auditoria contábil em 2025. Nessa situação, o recebimento desse crédito inscrito em dívida ativa resultou em aumento no resultado orçamentário de 2025. Certo Errado','[]'::jsonb,'C',2026,29,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — conforme o gabarito registrado no caderno.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13)"}'::jsonb,'Julgue o próximo item, a respeito de transferências voluntárias, receitas e despesas públicas e execução orçamentária. Considere que uma prefeitura tenha inscrito crédito fiscal de IPTU inadimplente, referente ao exercício de 2021, em dívida ativa durante auditoria contábil em 2025. Nessa situação, o recebimento desse crédito inscrito em dívida ativa resultou em aumento no resu') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4195370',2315,93,'P1','AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13)','FGV - ACE (TCE-PE)/TCE PE/Contas Públicas/2026','Caderno Contabilidade Pública Parte 5','Ao analisar o Balanço Orçamentário de uma entidade do setor público, um analista verificou os seguintes saldos relacionados às Receitas Orçamentárias: Previsão inicial: Amortizações de Empréstimos: R$200.000 Operações de Crédito: R$350.000 Receita Patrimonial: R$300.000 Impostos, Taxas e Contribuições de Melhoria: R$400.000 Previsão atualizada: Amortizações de Empréstimos: R$220.000 Operações de Crédito: R$360.000 Receita Patrimonial: R$306.000 Impostos, Taxas e Contribuições de Melhoria: R$392.000 Receitas realizadas: Amortizações de Empréstimos: R$225.000 Operações de Crédito: R$380.000 Receita Patrimonial: R$317.000 Impostos, Taxas e Contribuições de Melhoria: R$408.000 O analista pôde constatar que, ao apresentar o saldo, no subtotal de receitas, no Balanço Orçamentário, o montante decorrente das receitas de capital é','[["A","R$16.000."],["B","R$25.000."],["C","R$36.000."],["D","R$42.000."],["E","R$55.000."]]'::jsonb,'B',2026,30,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — R$25.000.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13)"}'::jsonb,'Ao analisar o Balanço Orçamentário de uma entidade do setor público, um analista verificou os seguintes saldos relacionados às Receitas Orçamentárias: Previsão inicial: Amortizações de Empréstimos: R$200.000 Operações de Crédito: R$350.000 Receita Patrimonial: R$300.000 Impostos, Taxas e Contribuições de Melhoria: R$400.000 Previsão atualizada: Amortizações de Empréstimos: R$22') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4216141',2316,93,'P1','AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13)','Instituto Verbena - FTrib (Pref Buriti Alegre)/Pref Buriti Alegre/2026','Caderno Contabilidade Pública Parte 5','Ao final do exercício financeiro, uma entidade do setor público verificou que a arrecadação das receitas orçamentárias ficou inferior à previsão inicial. A demonstração contábil que evidencia o confronto entre a previsão e a execução das receitas orçamentárias recebe a denominação de','[["A","Demonstração de Fluxo de Caixa."],["B","Demonstração das Variações Patrimoniais."],["C","Balanço Financeiro."],["D","Balanço Orçamentário."]]'::jsonb,'D',2026,31,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Balanço Orçamentário.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13)"}'::jsonb,'Ao final do exercício financeiro, uma entidade do setor público verificou que a arrecadação das receitas orçamentárias ficou inferior à previsão inicial. A demonstração contábil que evidencia o confronto entre a previsão e a execução das receitas orçamentárias recebe a denominação de') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4115621',2317,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - Tópicos Mesclados de Demonstrações Contábeis (MCASP, NBC TSP e Lei nº 4.320/1964)','AVANÇASP - Cont (CM Holambra)/CM Holambra/2026','Caderno Contabilidade Pública Parte 5','Relacione a Coluna I, que apresenta demonstrações contábeis aplicadas ao setor público (Lei nº 4.320/1964), com a Coluna II, que descreve o seu objetivo principal: COLUNA I I. Balanço Orçamentário II. Balanço Financeiro III. Balanço Patrimonial IV. Demonstração das Variações Patrimoniais COLUNA II (a) Demonstra as alterações verificadas no patrimônio, resultantes ou independentes da execução orçamentária, indicando o resultado patrimonial do exercício. (b) Demonstra as receitas e despesas previstas em confronto com as realizadas. (c) Demonstra o Ativo Financeiro e Permanente, o Passivo Financeiro e Permanente, o saldo patrimonial e as contas de compensação. (d) Demonstra a receita e a despesa orçamentárias e os recebimentos e pagamentos de natureza extraorçamentária, conjugados com os saldos em espécie. Assinale a alternativa que apresenta a associação CORRETA:','[["A","I-b, II-d, III-c, IV-a."],["B","I-b, II-c, III-d, IV-a."],["C","I-d, II-b, III-c, IV-a."],["D","I-b, II-d, III-a, IV-c."],["E","I-a, II-d, III-c, IV-b."]]'::jsonb,'A',2026,32,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Tópicos Mesclados de Demonstrações Contábeis (MCASP, NBC TSP e Lei nº 4.320/1964).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — I-b, II-d, III-c, IV-a.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Tópicos Mesclados de Demonstrações Contábeis (MCASP, NBC TSP e Lei nº 4.320/1964)"}'::jsonb,'Relacione a Coluna I, que apresenta demonstrações contábeis aplicadas ao setor público (Lei nº 4.320/1964), com a Coluna II, que descreve o seu objetivo principal: COLUNA I I. Balanço Orçamentário II. Balanço Financeiro III. Balanço Patrimonial IV. Demonstração das Variações Patrimoniais COLUNA II (a) Demonstra as alterações verificadas no patrimônio, resultantes ou independent') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4152828',2318,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - Tópicos Mesclados de Demonstrações Contábeis (MCASP, NBC TSP e Lei nº 4.320/1964)','IDECAN - Ana Leg (ALECE)/ALECE/Ciências Contábeis/2026','Caderno Contabilidade Pública Parte 5','No âmbito das demonstrações contábeis estabelecidas pela Lei nº 4.320/1964 e pelas Normas Brasileiras de Contabilidade Aplicadas ao Setor Público (NBC TSP), indique a alternativa correta.','[["A","O Balanço Financeiro demonstrará a receita e a despesa orçamentárias bem como os recebimentos e os pagamentos de natureza extraorçamentária, conjugados com os saldos em espécie provenientes do exercício anterior, e os que se transferem para o exercício seguinte."],["B","O Balanço Orçamentário demonstra a evolução do patrimônio líquido da entidade, evidenciando as mutações ocorridas durante o exercício financeiro."],["C","O Balanço Patrimonial é a demonstração que evidencia as receitas e despesas orçamentárias, bem como os ingressos e dispêndios extraorçamentários, conjugados com os saldos de caixa."],["D","A Demonstração das Variações Patrimoniais (DVP) deve ser elaborada exclusivamente com base na execução orçamentária, desconsiderando fatos meramente patrimoniais."],["E","A Demonstração dos Fluxos de Caixa (DFC) é facultativa para as entidades do setor público que já elaboram o Balanço Financeiro, visto que ambas possuem a mesma finalidade informativa."]]'::jsonb,'A',2026,33,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Tópicos Mesclados de Demonstrações Contábeis (MCASP, NBC TSP e Lei nº 4.320/1964).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — O Balanço Financeiro demonstrará a receita e a despesa orçamentárias bem como os recebimentos e os pagamentos de natureza extraorçamentária, conjugados com os saldos em espécie provenientes do exercício anterior, e os que se transferem para o exercício seguinte.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Tópicos Mesclados de Demonstrações Contábeis (MCASP, NBC TSP e Lei nº 4.320/1964)"}'::jsonb,'No âmbito das demonstrações contábeis estabelecidas pela Lei nº 4.320/1964 e pelas Normas Brasileiras de Contabilidade Aplicadas ao Setor Público (NBC TSP), indique a alternativa correta.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4075685',2319,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público','NOSSO RUMO - Cont (Pref SJBV)/Pref SJBV/2026','Caderno Contabilidade Pública Parte 5','A Secretaria Municipal de Saúde pretende implementar um sistema de gerenciamento de custos para avaliar a eficiência das Unidades de Pronto Atendimento (UPAs). O contador responsável pela modelagem precisa classificar os diversos gastos e definir os critérios de atribuição para que a informação gerada seja útil à governança e à avaliação de desempenho, permitindo inclusive a comparação entre diferentes unidades. Com base nas disposições da Norma Brasileira de Contabilidade (NBC-TSP 34/2021), assinale a alternativa que descreve o procedimento correto a ser adotado pelo contador.','[["A","O reconhecimento dos custos das UPAs no período deve seguir o momento do consumo dos recursos, sendo que os gastos com depreciação de equipamentos médicos e apropriação de 13º salário dos servidores são considerados custos por advirem de execução não orçamentária."],["B","Os custos relativos às atividades de vigilância e higienização das unidades de saúde devem ser classificados como custos finalísticos, visto que estão diretamente relacionados ao cumprimento da missão institucional de oferecer atendimento médico."],["C","Para que seja possível realizar uma análise comparativa fidedigna entre o custo de um atendimento médico na UPA da zona norte e na UPA da zona sul, o contador deve adotar obrigatoriamente o método de custeio variável."],["D","Na hierarquia de atribuição de custos aos atendimentos realizados, o contador deve priorizar a alocação dos custos indiretos mediante bases de rateio consistentes, para posterior identificação e apropriação dos custos diretos."],["E","Os recursos consumidos por uma UPA que não geram desembolso para a Secretaria de Saúde, como a atuação de profissionais cedidos por outro ente federativo, devem ser excluídos da apuração para não distorcer o custo real da unidade."]]'::jsonb,'A',2026,34,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — O reconhecimento dos custos das UPAs no período deve seguir o momento do consumo dos recursos, sendo que os gastos com depreciação de equipamentos médicos e apropriação de 13º salário dos servidores são considerados custos por advirem de execução não orçamentária.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público"}'::jsonb,'A Secretaria Municipal de Saúde pretende implementar um sistema de gerenciamento de custos para avaliar a eficiência das Unidades de Pronto Atendimento (UPAs). O contador responsável pela modelagem precisa classificar os diversos gastos e definir os critérios de atribuição para que a informação gerada seja útil à governança e à avaliação de desempenho, permitindo inclusive a co') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4075691',2320,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público','NOSSO RUMO - Cont (Pref SJBV)/Pref SJBV/2026','Caderno Contabilidade Pública Parte 5','Durante o processo de encerramento do exercício financeiro de uma Prefeitura, a equipe de contabilidade precisa consolidar as contas do ente e classificar os elementos patrimoniais no Balanço Patrimonial. O contador responsável depara-se com ativos de imobilizado mensurados por critérios distintos e obrigações financeiras cujo refinanciamento não depende de ato unilateral do município. Com base nas normas estabelecidas no Manual de Contabilidade Aplicada ao Setor Público (MCASP), 11ª Edição, e na Norma Brasileira de Contabilidade (NBC-TSP 34/2021), assinale a alternativa correta quanto aos procedimentos de análise e registro desses fatos.','[["A","O processo de consolidação das contas no âmbito do ente federado requer a manutenção dos saldos das contas intragovernamentais para que a visão patrimonial preserve a integridade dos registros realizados entre as secretarias municipais."],["B","A estrutura do Balanço Patrimonial adota a apresentação baseada na liquidez como modelo prioritário de divulgação, ficando a segregação entre itens circulantes e não circulantes restrita aos casos em que a informação fornecida seja considerada mais relevante."],["C","Itens como impostos a receber, multas e estoques, que são realizados no decurso do ciclo operacional normal da entidade, integram o ativo circulante, ainda que a expectativa de realização ocorra após o período de 12 (doze) meses da data das demonstrações contábeis."],["D","O potencial de refinanciamento de uma dívida municipal é considerado suficiente para fundamentar sua classificação como passivo não circulante nos casos em que a renovação do acordo depende de aceitação futura por parte da instituição financeira credora."],["E","A utilização de critérios de mensuração similares para classes distintas de ativos implica a necessidade de apresentação em contas separadas, visando ao fornecimento de informação relevante sobre a função dos bens na estrutura da entidade."]]'::jsonb,'C',2026,35,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Itens como impostos a receber, multas e estoques, que são realizados no decurso do ciclo operacional normal da entidade, integram o ativo circulante, ainda que a expectativa de realização ocorra após o período de 12 (doze) meses da data das demonstrações contábeis.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público"}'::jsonb,'Durante o processo de encerramento do exercício financeiro de uma Prefeitura, a equipe de contabilidade precisa consolidar as contas do ente e classificar os elementos patrimoniais no Balanço Patrimonial. O contador responsável depara-se com ativos de imobilizado mensurados por critérios distintos e obrigações financeiras cujo refinanciamento não depende de ato unilateral do mu') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4089351',2321,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público','Legalle - Cont (CISCOPAR)/CISCOPAR/2026','Caderno Contabilidade Pública Parte 5','No contexto da contabilidade de custos aplicada a um Consórcio Público Intermunicipal de Saúde, o instrumento utilizado para identificar a relação de causa e efeito entre a ocorrência de determinados custos e os objetos de custeio, possibilitando a adequada alocação dos custos indiretos aos serviços prestados, é denominado:','[["A","Direcionador de custo."],["B","Centro de responsabilidade de custo."],["C","Sistema de apropriação de custos indiretos."],["D","Sistema de acumulação de custos."]]'::jsonb,'A',2026,36,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Direcionador de custo.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público"}'::jsonb,'No contexto da contabilidade de custos aplicada a um Consórcio Público Intermunicipal de Saúde, o instrumento utilizado para identificar a relação de causa e efeito entre a ocorrência de determinados custos e os objetos de custeio, possibilitando a adequada alocação dos custos indiretos aos serviços prestados, é denominado:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4114011',2322,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público','VUNESP - Cont (CM Votorantim)/CM Votorantim/2026','Caderno Contabilidade Pública Parte 5','Com base nas diretrizes da NBC TSP nº 34/2021, que trata de custos aplicados ao setor público, assinale a alternativa que apresenta o procedimento correto para que uma entidade pública estruture a apuração dos custos dos serviços entregues à sociedade, considerando o consumo de recursos, a definição dos objetos de custo e a forma de atribuição dos custos diretos e indiretos.','[["A","Na apuração de custos no setor público, a entidade deve observar exclusivamente o regime de caixa, reconhecendo como custo apenas os recursos efetivamente pagos no período, pois a informação de custos deve refletir o desembolso financeiro realizado pela entidade e a execução orçamentária correspondente."],["B","A entidade deve identificar, acumular e relatar os custos de seus objetos em base regular; o custo do período deve ser apurado pelo regime de competência; e a atribuição dos custos deve priorizar a apropriação dos custos diretos, seguida da alocação dos custos indiretos por direcionadores e, em último caso, por bases de rateio razoáveis e consistentes."],["C","O objeto de custo final corresponde a qualquer unidade administrativa interna, ainda que não represente bem ou serviço entregue à sociedade, desde que essa unidade consuma recursos orçamentários, financeiros ou patrimoniais no período e possua centro de responsabilidade definido no sistema gerencial."],["D","Os custos indiretos devem ser alocados, pela entidade pública, diretamente aos objetos de custo, sem necessidade de direcionadores ou critérios consistentes de rateio, pois a finalidade da informação gerencial é apenas estimar o consumo total de recursos, ainda que sem relação de causa e efeito com a entrega realizada."],["E","A inexistência de sistema informatizado robusto ou o pequeno porte da entidade justificam a ausência de iniciativas para desenvolvimento de informações de custos, especialmente quando houver limitação de pessoal, tecnologia ou bases de dados, ainda que existam controles simplificados."]]'::jsonb,'B',2026,37,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — A entidade deve identificar, acumular e relatar os custos de seus objetos em base regular; o custo do período deve ser apurado pelo regime de competência; e a atribuição dos custos deve priorizar a apropriação dos custos diretos, seguida da alocação dos custos indiretos por direcionadores e, em último caso, por bases de rateio razoáveis e consistentes.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público"}'::jsonb,'Com base nas diretrizes da NBC TSP nº 34/2021, que trata de custos aplicados ao setor público, assinale a alternativa que apresenta o procedimento correto para que uma entidade pública estruture a apuração dos custos dos serviços entregues à sociedade, considerando o consumo de recursos, a definição dos objetos de custo e a forma de atribuição dos custos diretos e indiretos.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4130009',2323,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público','CEBRASPE (CESPE) - EGP (SEPLAG AL)/SEPLAG AL/Contabilidade/2026','Caderno Contabilidade Pública Parte 5','Acerca da apuração de custos no setor público e do plano de contas aplicado ao setor público (PCASP), julgue o item a seguir. A definição de custo se refere ao consumo ou à utilização de recursos para a geração de bens ou serviços, enquanto a perda representa o consumo anormal e imprevisível. Certo Errado','[]'::jsonb,'C',2026,38,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — conforme o gabarito registrado no caderno.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público"}'::jsonb,'Acerca da apuração de custos no setor público e do plano de contas aplicado ao setor público (PCASP), julgue o item a seguir. A definição de custo se refere ao consumo ou à utilização de recursos para a geração de bens ou serviços, enquanto a perda representa o consumo anormal e imprevisível. Certo Errado') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4130010',2324,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público','CEBRASPE (CESPE) - EGP (SEPLAG AL)/SEPLAG AL/Contabilidade/2026','Caderno Contabilidade Pública Parte 5','Acerca da apuração de custos no setor público e do plano de contas aplicado ao setor público (PCASP), julgue o item a seguir. Para ser útil e compreensível ao usuário, a informação de custos deve levar em consideração as características qualitativas de relevância, representação fidedigna e comparabilidade. Certo Errado','[]'::jsonb,'C',2026,39,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — conforme o gabarito registrado no caderno.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público"}'::jsonb,'Acerca da apuração de custos no setor público e do plano de contas aplicado ao setor público (PCASP), julgue o item a seguir. Para ser útil e compreensível ao usuário, a informação de custos deve levar em consideração as características qualitativas de relevância, representação fidedigna e comparabilidade. Certo Errado') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.priorid