INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4150546',2325,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público','FUNDATEC - Ana Pol Pen (PP RS)/PP RS/Ciências Contábeis/2026','Caderno Contabilidade Pública Parte 5','No contexto da NBC TSP 34 (Custos no Setor Público), assinale a alternativa que apresenta o indicador que permite estabelecer a relação de causa e efeito para alocação dos custos indiretos.','[["A","Gasto."],["B","Desembolso."],["C","Custo Fixo."],["D","Direcionador de custo."],["E","Custo Controlável."]]'::jsonb,'D',2026,40,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Direcionador de custo.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público"}'::jsonb,'No contexto da NBC TSP 34 (Custos no Setor Público), assinale a alternativa que apresenta o indicador que permite estabelecer a relação de causa e efeito para alocação dos custos indiretos.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4152835',2326,83,'P1','AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público','IDECAN - Ana Leg (ALECE)/ALECE/Ciências Contábeis/2026','Caderno Contabilidade Pública Parte 5','Conforme a NBC TSP 34, o reconhecimento e a mensuração dos custos devem observar critérios que permitam a avaliação do desempenho e a tomada de decisão. Considerando as formas de mensuração de ativos e passivos para fins de apuração de custos, assinale a alternativa correta.','[["A","O custo total de um serviço público deve considerar apenas os desembolsos financeiros efetuados no exercício, ignorando o regime de competência para evitar distorções no fluxo de caixa da entidade."],["B","O custo de oportunidade, no setor público, representa o valor que seria obtido caso o recurso fosse aplicado em uma alternativa de uso, sendo essencial para evidenciar o benefício econômico que a entidade renunciou ao escolher uma determinada linha de ação."],["C","O custo de reposição não é aceito como critério de mensuração para a contabilidade de custos pública, devendo-se utilizar estritamente o valor de aquisição histórico sem ajustes por inflação ou obsolescência."],["D","Os custos indiretos de produção, por serem de difícil atribuição, devem ser lançados diretamente como despesas do período (variação patrimonial diminutiva), sem integrar o valor dos estoques ou dos serviços prestados."],["E","A depreciação, a amortização e a exaustão são consideradas variações patrimoniais qualitativas e, portanto, não devem compor a base de cálculo dos custos dos serviços públicos."]]'::jsonb,'B',2026,41,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — O custo de oportunidade, no setor público, representa o valor que seria obtido caso o recurso fosse aplicado em uma alternativa de uso, sendo essencial para evidenciar o benefício econômico que a entidade renunciou ao escolher uma determinada linha de ação.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - NBC TSP 34 - Custos no Setor Público"}'::jsonb,'Conforme a NBC TSP 34, o reconhecimento e a mensuração dos custos devem observar critérios que permitam a avaliação do desempenho e a tomada de decisão. Considerando as formas de mensuração de ativos e passivos para fins de apuração de custos, assinale a alternativa correta.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4150561',2327,92,'P1','AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)','FUNDATEC - Ana Pol Pen (PP RS)/PP RS/Ciências Contábeis/2026','Caderno Contabilidade Pública Parte 5','Nos termos da LRF, se a despesa total com pessoal de um Poder ou órgão ultrapassar o limite legal, o percentual excedente deverá ser eliminado:','[["A","Nos dois quadrimestres seguintes, sendo pelo menos um terço no primeiro."],["B","No exercício seguinte, sendo pelo menos a metade no primeiro semestre."],["C","Em até três quadrimestres consecutivos, em parcelas iguais."],["D","No quadrimestre subsequente, de forma integral."],["E","No prazo de doze meses, sendo 50% nos primeiros seis meses."]]'::jsonb,'A',2026,42,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — Nos dois quadrimestres seguintes, sendo pelo menos um terço no primeiro.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)"}'::jsonb,'Nos termos da LRF, se a despesa total com pessoal de um Poder ou órgão ultrapassar o limite legal, o percentual excedente deverá ser eliminado:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4150598',2328,92,'P1','AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)','FUNDATEC - Ana Pol Pen (PP RS)/PP RS/Ciências Contábeis/2026','Caderno Contabilidade Pública Parte 5','Quando o montante da despesa total com pessoal exceder a 95% do limite, o Poder ou órgão fica sujeito a restrições imediatas. Nesse cenário, assinale a alternativa que apresenta uma conduta permitida.','[["A","Alteração de estrutura de carreira que implique aumento de despesa, visando à retenção de talentos."],["B","Concessão de vantagem ou aumento de remuneração a qualquer título, desde que previsto na LDO."],["C","Criação de novos cargos ou funções para atender à expansão de serviços públicos essenciais."],["D","Reposição decorrente de falecimento de servidores da área da saúde."],["E","Contratação de horas extras, independentemente da situação que lhe deu origem, para suprir carência de pessoal."]]'::jsonb,'D',2026,43,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Reposição decorrente de falecimento de servidores da área da saúde.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)"}'::jsonb,'Quando o montante da despesa total com pessoal exceder a 95% do limite, o Poder ou órgão fica sujeito a restrições imediatas. Nesse cenário, assinale a alternativa que apresenta uma conduta permitida.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4155539',2329,92,'P1','AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)','IDECAN - Ana Leg (ALECE)/ALECE/Planejamento e Orçamento/2026','Caderno Contabilidade Pública Parte 5','A Lei de Responsabilidade Fiscal estabelece limites percentuais para a despesa total com pessoal dos entes federativos, calculados sobre a receita corrente líquida. Esses limites visam assegurar o equilíbrio fiscal e evitar o comprometimento excessivo do orçamento com folha de pagamento. Sobre os limites de despesa com pessoal previstos na LRF, assinale a alternativa correta.','[["A","A União não possui limite de despesa com pessoal, pois a LRF apenas fixa limites para Estados e Municípios."],["B","Os Estados e o Distrito Federal podem comprometer até 70% da receita corrente líquida com despesas de pessoal, incluídas as empresas estatais dependentes."],["C","A LRF permite que as despesas de pessoal cresçam livremente no caso de aumento de receita tributária, dispensando limites percentuais."],["D","Se extrapolado o limite de despesa com pessoal, o ente deverá eliminar o percentual excedente nos dois quadrimestres seguintes, adotando medidas como a redução de cargos em comissão e a exoneração de servidores estáveis."],["E","Os limites de despesa com pessoal não se aplicam aos gastos com inativos e pensionistas, por serem despesas previdenciárias."]]'::jsonb,'D',2026,44,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Se extrapolado o limite de despesa com pessoal, o ente deverá eliminar o percentual excedente nos dois quadrimestres seguintes, adotando medidas como a redução de cargos em comissão e a exoneração de servidores estáveis.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)"}'::jsonb,'A Lei de Responsabilidade Fiscal estabelece limites percentuais para a despesa total com pessoal dos entes federativos, calculados sobre a receita corrente líquida. Esses limites visam assegurar o equilíbrio fiscal e evitar o comprometimento excessivo do orçamento com folha de pagamento. Sobre os limites de despesa com pessoal previstos na LRF, assinale a alternativa correta.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4189308',2330,92,'P1','AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)','FGV - NAC UNI OAB/OAB/2026','Caderno Contabilidade Pública Parte 5','O Banco XYZ S.A., sociedade de economia mista federal (estatal não dependente) e que não faz uso de recursos públicos para pagamento de pessoal, recebeu uma equipe de fiscalização do Tribunal de Contas da União (TCU), que desejava saber, entre outras questões, o valor das remunerações pagas aos diretores do banco, para fins de cálculo do limite de despesas totais com pessoal previstas na Lei Complementar nº 101/2000 (Lei de Responsabilidade Fiscal - LRF). Constatando que os diretores recebiam acima do teto remuneratório constitucional (a saber, o subsídio dos Ministros do Supremo Tribunal Federal - STF), o TCU determinou que as remunerações dos diretores fossem limitadas ao teto constitucional, deixando de computar o excesso remuneratório acima do teto para a apuração da despesa total com pessoal prevista na LRF. Sobre a hipótese apresentada, assinale a afirmativa correta.','[["A","O Banco XYZ S.A., por se tratar de uma empresa estatal não dependente, não se submete aos limites de despesa total com pessoal previstos na LRF."],["B","Os dirigentes do referido banco, nos termos da LRF, podem ser pessoalmente responsabilizados pelo excesso remuneratório acima do teto efetivamente recebido."],["C","O TCU deveria ter computado o excesso remuneratório acima do teto efetivamente pago aos dirigentes do Banco XYZ S.A. para a apuração da despesa total com pessoal prevista na LRF."],["D","A LRF veda, expressamente, o pagamento de remuneração a dirigentes de instituições financeiras estatais não dependentes que suplantem o teto remuneratório constitucional."]]'::jsonb,'A',2026,45,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — O Banco XYZ S.A., por se tratar de uma empresa estatal não dependente, não se submete aos limites de despesa total com pessoal previstos na LRF.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)"}'::jsonb,'O Banco XYZ S.A., sociedade de economia mista federal (estatal não dependente) e que não faz uso de recursos públicos para pagamento de pessoal, recebeu uma equipe de fiscalização do Tribunal de Contas da União (TCU), que desejava saber, entre outras questões, o valor das remunerações pagas aos diretores do banco, para fins de cálculo do limite de despesas totais com pessoal pr') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4090432',2331,85,'P1','AFO, Direito Financeiro e Contabilidade Pública - Manual de Demonstrativos Fiscais','Legalle - Con Leg (CM Cerro Largo)/CM Cerro Largo/2026','Caderno Contabilidade Pública Parte 5','Com base na Lei de Responsabilidade Fiscal (LRF) e no Manual de Demonstrativos Fiscais (MDF), assinale a alternativa que NÃO CORRESPONDE a um demonstrativo que acompanha o Relatório Resumido de Execução Orçamentária (RREO).','[["A","Balanço orçamentário."],["B","Disponibilidade de caixa e dos restos a pagar."],["C","Resultados primário e nominal."],["D","Receita corrente líquida."]]'::jsonb,'B',2026,46,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Manual de Demonstrativos Fiscais.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Disponibilidade de caixa e dos restos a pagar.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Manual de Demonstrativos Fiscais"}'::jsonb,'Com base na Lei de Responsabilidade Fiscal (LRF) e no Manual de Demonstrativos Fiscais (MDF), assinale a alternativa que NÃO CORRESPONDE a um demonstrativo que acompanha o Relatório Resumido de Execução Orçamentária (RREO).') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, 