INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4115625',2332,85,'P1','AFO, Direito Financeiro e Contabilidade Pública - Manual de Demonstrativos Fiscais','AVANÇASP - Cont (CM Holambra)/CM Holambra/2026','Caderno Contabilidade Pública Parte 5','De acordo com o Manual de Demonstrativos Fiscais (MDF), 15ª Edição, na seção Apresentação, a publicação da Lei Complementar nº 156/2016 alterou o art. 48 da LRF, obrigando o envio dos demonstrativos fiscais (RREO e RGF) por todos os Poderes e órgãos dos entes da Federação ao __________ e a disponibilização desses dados em meios eletrônicos de amplo acesso público. Além do envio dos demonstrativos, os entes também passaram a disponibilizar a __________, que é uma estrutura criada pela STN para permitir a geração automática dos demonstrativos fiscais no padrão definido pelo MDF. Assinale a alternativa que preenche correta e respectivamente as lacunas do texto:','[["A","Sistema Integrado de Administração Financeira do Governo Federal (SIAFI) / Matriz de Saldos Contábeis (MSC)."],["B","Sistema de Informações Contábeis e Fiscais do Setor Público Brasileiro (Siconfi) / Demonstração das Variações Patrimoniais (DVP)."],["C","Sistema de Informações Contábeis e Fiscais do Setor Público Brasileiro (Siconfi) / Matriz de Saldos Contábeis (MSC)."],["D","Sistema Integrado de Administração Financeira do Governo Federal (SIAFI) / Conta Única do Tesouro Nacional."],["E","Conselho de Gestão Fiscal (CGF) / Matriz de Saldos Contábeis (MSC)."]]'::jsonb,'C',2026,47,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Manual de Demonstrativos Fiscais.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Sistema de Informações Contábeis e Fiscais do Setor Público Brasileiro (Siconfi) / Matriz de Saldos Contábeis (MSC).","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Manual de Demonstrativos Fiscais"}'::jsonb,'De acordo com o Manual de Demonstrativos Fiscais (MDF), 15ª Edição, na seção Apresentação, a publicação da Lei Complementar nº 156/2016 alterou o art. 48 da LRF, obrigando o envio dos demonstrativos fiscais (RREO e RGF) por todos os Poderes e órgãos dos entes da Federação ao __________ e a disponibilização desses dados em meios eletrônicos de amplo acesso público. Além do envio') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4142310',2333,85,'P1','AFO, Direito Financeiro e Contabilidade Pública - Manual de Demonstrativos Fiscais','CEBRASPE (CESPE) - Aud (CGM Porto Velho)/Pref Porto Velho/2026','Caderno Contabilidade Pública Parte 5','No que diz respeito às finalidades e características do relatório resumido da execução orçamentária (RREO) e do relatório de gestão fiscal (RGF), assinale a opção correta.','[["A","O demonstrativo simplificado do RREO exclui as receitas e despesas intraorçamentárias para evitar duplicidade na consolidação das contas públicas."],["B","O demonstrativo simplificado do RREO evidencia, em um único instrumento, informações como resultado primário e nominal, receita corrente líquida, restos a pagar e aplicação mínima em saúde e educação."],["C","O RGF deve ser elaborado bimestralmente e apresentar informações extraídas do balanço orçamentário para demonstrar a execução da receita e da despesa acumuladas até o bimestre de referência."],["D","O demonstrativo simplificado do RREO, emitido ao final de cada quadrimestre pelos titulares dos Poderes e órgãos, deve conter os limites de despesa com pessoal."],["E","O RGF tem como principal objetivo demonstrar as previsões inicial e atualizada da receita e da despesa constantes na LOA."]]'::jsonb,'B',2026,48,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Manual de Demonstrativos Fiscais.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — O demonstrativo simplificado do RREO evidencia, em um único instrumento, informações como resultado primário e nominal, receita corrente líquida, restos a pagar e aplicação mínima em saúde e educação.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Manual de Demonstrativos Fiscais"}'::jsonb,'No que diz respeito às finalidades e características do relatório resumido da execução orçamentária (RREO) e do relatório de gestão fiscal (RGF), assinale a opção correta.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3775825',2334,73,'P2','AFO, Direito Financeiro e Contabilidade Pública - Procedimentos Contábeis Específicos (RPPS, FUNDEB, etc.)','Fênix Instituto - Con (Pref Brunópolis)/Pref Brunópolis/2026','Caderno Contabilidade Pública Parte 5','Nos termos do MCASP, quanto aos Recursos Arrecadados em Exercícios Anteriores (RAEA) referente aos RPPS, analise as assertivas: I. A conta 8.2.1.1.1.02.xx DDR – Recursos de Exercícios Anteriores registra o valor das disponibilidades provenientes de recursos de exercícios anteriores, cuja execução depende de autorização. II. A conta 8.2.1.1.1.02.xx DDR – Recursos de Exercícios Anteriores tem natureza devedora e inverte saldo. III. Quando da utilização desses recursos no exercício corrente, além dos registros nas contas de execução orçamentária, registra-se os valores autorizados em contas de controle. Está(ão) CORRETA(S):','[["A","Apenas III."],["B","Apenas I e II."],["C","Apenas I e III."],["D","I, II e III."]]'::jsonb,'C',2026,49,NULL,NULL,'{"regra":"A resolução deve aplicar a regra orçamentária, financeira ou contábil pública pertinente ao tema, respeitando a classificação e o estágio indicados no enunciado.","passos":["Identifique o núcleo do tema: AFO, Direito Financeiro e Contabilidade Pública - Procedimentos Contábeis Específicos (RPPS, FUNDEB, etc.).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Apenas I e III.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Procedimentos Contábeis Específicos (RPPS, FUNDEB, etc.)"}'::jsonb,'Nos termos do MCASP, quanto aos Recursos Arrecadados em Exercícios Anteriores (RAEA) referente aos RPPS, analise as assertivas: I. A conta 8.2.1.1.1.02.xx DDR – Recursos de Exercícios Anteriores registra o valor das disponibilidades provenientes de recursos de exercícios anteriores, cuja execução depende de autorização. II. A conta 8.2.1.1.1.02.xx DDR – Recursos de Exercícios A') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
