],"fundamento":"AFO, Direito Financeiro e Contabilidade Pública - Procedimentos Contábeis Específicos (RPPS, FUNDEB, etc.)"}'::jsonb,'Para o Reconhecimento inicial do benefício previdenciário, aposentadoria ou pensão, por competência no RPPS, contabiliza-se como Natureza da Informação Patrimonial:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
